insert into public.search_synonyms as s (kind, target, words, shown, updated_by)
select 'shop', target, words, shown, '기본' from v
on conflict (kind, target) do update set
  -- 띄어쓰기 · 대소문자만 다른 말은 한 번만
  words = s.words || array(select w from unnest(excluded.words) w
                           where not (lower(replace(w, ' ', '')) = any(array(select lower(replace(o, ' ', '')) from unnest(s.words) o)))),
  -- 관리자가 아직 손대지 않은 업체(기본)는 이 목록으로 바꾸고, 손댄 업체는 빈 자리만 채워요
  shown = case when s.updated_by = '기본' then excluded.shown
               else (s.shown || array(select w from unnest(excluded.shown) w
                                      where not (lower(replace(w, ' ', '')) = any(array(select lower(replace(o, ' ', '')) from unnest(s.shown) o)))))[1:10] end,
  updated_at = now();

-- 확인
select count(*) as 업체, sum(cardinality(words)) as 검색어, sum(cardinality(shown)) as 해시태그 from public.search_synonyms where kind = 'shop';
